import{_ as e,a as r,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 39 蹇：看见险阻而能停下至比较与自测","description":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","frontmatter":{"title":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 39 蹇：看见险阻而能停下至比较与自测","description":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","splitFrom":"life/personal/yijing/hexagrams-33-40.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解","summary":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 36 明夷：受伤的光明如何保存至38 睽：差异不必变成敌意","link":"/life/personal/yijing/hexagrams-33-40-part-02"},"next":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井","link":"/life/personal/yijing/hexagrams-41-48"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 36 明夷：受伤的光明如何保存至38 睽：差异不必变成敌意","link":"/life/personal/yijing/hexagrams-33-40-part-02"},"next":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井","link":"/life/personal/yijing/hexagrams-41-48"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-33-40-part-03.md","filePath":"life/personal/yijing/hexagrams-33-40-part-03.md"}'),o={name:"life/personal/yijing/hexagrams-33-40-part-03.md"};function i(s,t,d,l,p,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读-三十三至四十-遯、大壮、晋、明夷、家人、睽、蹇、解-·-39-蹇-看见险阻而能停下至比较与自测" tabindex="-1">六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 39 蹇：看见险阻而能停下至比较与自测 <a class="header-anchor" href="#六十四卦详读-三十三至四十-遯、大壮、晋、明夷、家人、睽、蹇、解-·-39-蹇-看见险阻而能停下至比较与自测" aria-label="Permalink to &quot;六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 39 蹇：看见险阻而能停下至比较与自测&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-33-40">返回分篇目录</a></p><p>本篇将经文、传文与现代概括分开：<strong>卦辞、爻辞</strong>是《周易》经文，<strong>大象</strong>出自《象传》；表中解释和“读法”是依据原文及古注所作的现代概括。爻从下向上读，初爻并不必然代表某个年龄，上爻也不是固定的结局。古注采用王弼注、孔颖达疏《周易正义》，它是重要的解释传统，不是经文的唯一可能含义。所引古籍为公有领域文本；电子本中的异体字、断句仍须留意。</p><p>这一组可成对比较：遯与大壮讨论退与强，晋与明夷讨论光明的显与藏，家人与睽讨论共同生活与分歧，蹇与解讨论困阻与舒解。“吉凶”保留为古代占筮判断，不作现实事件的科学预测。</p><h2 id="gua-39" tabindex="-1">39 蹇：看见险阻而能停下 <a class="header-anchor" href="#gua-39" aria-label="Permalink to &quot;39 蹇：看见险阻而能停下 {#gua-39}&quot;">​</a></h2><p><strong>卦符：䷦｜上卦坎 ☵（水、险），下卦艮 ☶（山、止）。</strong>“蹇”读 jiǎn，本有行走困难之意；山与水重叠，象征通路受阻。</p><p><strong>卦辞原文：</strong></p><blockquote><p>蹇：利西南，不利東北；利見大人，貞吉。</p></blockquote><p><strong>白话概括：</strong> 遇险应选择较平易的方向，寻求有能力共同解难者，并坚持正当。《正义》以西南为平地、东北为山险解释方向，这是其象征系统；不可未经现实判断就据此安排旅行、迁居或投资方位。“大人”也不是固定指有钱有权的人。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>往蹇，來譽。</td><td>径直向前受阻，回来等待反获称许；暂停能是审慎选择，不必为面子继续投入。</td></tr><tr><td>六二</td><td>王臣蹇蹇，匪躬之故。</td><td>臣子为公事反复涉难，并非为个人利益；说明有些承担不能简单等同于逞强。</td></tr><tr><td>九三</td><td>往蹇來反。</td><td>前行不通则返回原有基础；古注联系内部相待，提醒回返并非全然没有依托。</td></tr><tr><td>六四</td><td>往蹇來連。</td><td>独自前往困难，回来联合相助；“连”着重关系连接，不能把所有难处交给个人硬扛。</td></tr><tr><td>九五</td><td>大蹇朋來。</td><td>最大困难中有朋友来助；得助与平日立身、共同关系有关，不是无条件的贵人承诺。</td></tr><tr><td>上六</td><td>往蹇來碩，吉；利見大人。</td><td>前往仍难，回返获得较大成果；与有德有能者相接，重在改变应对路径。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>山上有水，蹇；君子以反身修德。</p></blockquote><p><strong>大象解释：</strong> 外部道路受阻时，回看自身可以改善之处。反省与寻求帮助并行，不能推成“所有困难都是受困者品德不好”。</p><p><strong>整体读法与误区：</strong>“往蹇来……”反复出现，是本卦最明显的语言结构。比较初爻的等待、四爻的联合、五爻的朋友与二爻的尽职，能看出停止和承担并不矛盾。现代阅读可列出阻碍中的外因、可控因素与支持资源，避免把反省变成自责。它也不主张一遇困难就放弃；关键是先辨认所走的路径是否进一步增加风险。</p><p><strong>经传对读：</strong>“来誉、来反、来连、朋来、来硕”的变化，把回返逐渐写为等待、返回、联合与获得援助。六二是显著例外：它不以“往来”重复句式展开，而写为公事承担连续艰难。把这一例外保留下来，就能避免把整卦读成一律后退；所谓知止还要同时考虑角色责任和谁会承担退出的后果。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B9%87" target="_blank" rel="noopener noreferrer">《周易·蹇》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E8%B9%87" target="_blank" rel="noopener noreferrer">《周易正义》卷四·蹇</a>。</p><h2 id="gua-40" tabindex="-1">40 解：困难解除后回到常态 <a class="header-anchor" href="#gua-40" aria-label="Permalink to &quot;40 解：困难解除后回到常态 {#gua-40}&quot;">​</a></h2><p><strong>卦符：䷧｜上卦震 ☳（雷、动），下卦坎 ☵（水、险）。</strong>“解”取松解、解除之义，传统读作 xiè；今天也常按“解难”的 jiě 来理解。动而出险，是与蹇相接的重点。</p><p><strong>卦辞原文：</strong></p><blockquote><p>解：利西南，无所往，其來復吉。有攸往，夙吉。</p></blockquote><p><strong>白话概括：</strong> 若已没有需要解决的事情，就恢复正常；仍有待解的难题，则及早处理。《正义》特别指出两个相反错误：无事却强求立功，有事却等到败坏才救。这一判断比笼统说“行动就好”更具体。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>无咎。</td><td>解难初时处在刚柔相接处，《小象》认为可无过；短句不能脱离位置直接扩成事事顺利。</td></tr><tr><td>九二</td><td>田獲三狐，得黃矢，貞吉。</td><td>狩猎除狐而得黄箭，古注借狐说明隐伏的邪曲，以黄、直说明中正；保留狩猎画面更易看出比喻。</td></tr><tr><td>六三</td><td>負且乘，致寇至，貞吝。</td><td>背负物品却乘高位之车，身份行为错置而招险；这是古代等级叙事，不应用来责备现实受害者。</td></tr><tr><td>九四</td><td>解而拇，朋至斯孚。</td><td>解开与“拇”的牵系，可信赖的伙伴才到来；古注重在解除不当依附，并非身体治疗方法。</td></tr><tr><td>六五</td><td>君子惟有解，吉；有孚于小人。</td><td>君子确实实行解除，才显出可信的效果；《小象》以小人退去说明，不只靠口头宣称。</td></tr><tr><td>上六</td><td>公用射隼，于高墉之上，獲之，无不利。</td><td>隼栖高墙，待工具和条件具备而射获，象征处理仍据险的障碍；不是向私人暴力发许可证。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>雷雨作，解；君子以赦過宥罪。</p></blockquote><p><strong>大象解释：</strong> 雷雨舒解闭塞，引出宽宥过失、减轻罪罚的政治伦理。它体现复常与松解，但不是现代法律具体如何处理案件的依据。</p><p><strong>整体读法与误区：</strong> 解卦既有清除障碍，也有宽宥与回归常态，不能只取“惩治坏人”的一面。现代可借来检视问题解决后的收尾：临时限制是否应解除，遗留风险是否需及时处理，是否仍在以危机方式维持日常。不同情境的宽恕、责任与补救要分别讨论，不能靠“解”字抹平。</p><p><strong>经传对读：</strong> 初六只有“无咎”，上六却有射获高墙之隼，中间经历辨除隐患、摆脱不当依附和恢复信任。大象又加入赦宥，表明解除局面既有必要处置，也有停止追究的一面。读者可以标出哪些句子指向仍需做的事，哪些指向应放下的事，再理解“无所往”与“有攸往”的差别。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%A3" target="_blank" rel="noopener noreferrer">《周易·解》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E8%A7%A3" target="_blank" rel="noopener noreferrer">《周易正义》卷四·解</a>。</p><h2 id="比较与自测" tabindex="-1">比较与自测 <a class="header-anchor" href="#比较与自测" aria-label="Permalink to &quot;比较与自测 {#比较与自测}&quot;">​</a></h2><ol><li>遯的“退”和蹇的“来”分别回应什么处境？为什么都不能简单译作逃避？</li><li>大壮的羊角、晋上九的角，怎样共同限制“力量越大越好”的解释？</li><li>家人的“行有恒”与睽的“同而异”能否同时成立？哪些属于古代制度背景？</li><li>解卦为什么同时说“来复吉”和“夙吉”？请先判断是否仍有需要处理的难题。</li></ol><p>继续阅读：<a href="/life/personal/yijing/hexagrams-41-48">第四十一至四十八卦</a> · 返回 <a href="/life/personal/yijing/overview">易经专题导读</a>。</p>',33)])])}const u=e(o,[["render",i]]);export{c as __pageData,u as default};
